     * Check if the value passed can be cast to a string.
     *
     * @param mixed $value
     *
     * @return bool
     */
    private function valueCanBeString($value): bool
    {
        return is_string($value) || is_scalar($value) || (is_object($value) && method_exists($value, '__toString'));
    }
